import{_ as t,o as e,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-22（古人类学 / 古蛋白质组）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/paleoanthropology/science-daily-2026-10-22-paleo.md","filePath":"topics/paleoanthropology/science-daily-2026-10-22-paleo.md"}'),s={name:"topics/paleoanthropology/science-daily-2026-10-22-paleo.md"};function a(l,o,i,c,g,p){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-22-古人类学-古蛋白质组" tabindex="-1">科学日报 · 2026-10-22（古人类学 / 古蛋白质组） <a class="header-anchor" href="#科学日报-·-2026-10-22-古人类学-古蛋白质组" aria-label="Permalink to &quot;科学日报 · 2026-10-22（古人类学 / 古蛋白质组）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> — 第41期 ｜ 科学板块 落盘说明：文件名带 <code>-paleo</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-22-神秘丹尼索瓦人的长相——许家窑中更新世化石的古蛋白质组证据" tabindex="-1">科学日报 2026-10-22：神秘丹尼索瓦人的长相——许家窑中更新世化石的古蛋白质组证据 <a class="header-anchor" href="#科学日报-2026-10-22-神秘丹尼索瓦人的长相——许家窑中更新世化石的古蛋白质组证据" aria-label="Permalink to &quot;科学日报 2026-10-22：神秘丹尼索瓦人的长相——许家窑中更新世化石的古蛋白质组证据&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ DOI: 10.1038/s41586-026-11132-z</p></blockquote><ul><li>问题：东亚晚中更新世古人类的<strong>分类与系统发育</strong>长期争议不断。<strong>许家窑</strong>是化石丰富、地层清晰的关键地点（约 <strong>19.9–13.8 万年前</strong>），但其演化位置一直不明。</li><li>方法：对两件标本做<strong>古蛋白质组（palaeoproteomics）<strong>分析 —— 得到 <strong>18 种内源蛋白</strong>；其中</strong>丹尼索瓦人特有的 COL1A2-996 R&gt;K 突变</strong>强烈支持其归属丹尼索瓦支系。再与其它东亚晚中更新世古老型人类做形态比较。</li><li>结果： <ul><li><strong>支系扩容</strong>：许家窑、哈尔滨与<strong>金牛山、大荔、华龙洞</strong>共享一组形态特征 → 同属丹尼索瓦支系。</li><li><strong>面貌画像（混合性状）</strong>：类似<strong>直立人</strong>（厚颅壁）；<strong>现代人</strong>特征（强弓形颞鳞）；共享<strong>晚尼安德特人</strong>部分特征（颞骨迷路结构、枕上凹）。</li><li><strong>独特性状</strong>：低平颅侧廓 + <strong>近平行侧壁</strong>、厚重眶上圆枕、扁平颧上颌区、<strong>弱颌突</strong>。</li></ul></li><li>结论：这是迄今最完整的一次「<strong>给丹尼索瓦人画脸</strong>」——把此前只有零星指骨/牙齿/下颌的支系，接上了一整套可量化的颅骨形态特征。</li><li>洞察（对本库 <code>paleoanthropology</code>）：这条的第一序意义是<strong>方法</strong>，不是结论 —— <strong>蛋白质（尤其胶原）比 DNA 更能穿透时间与气候窗口</strong>。库内 10-12（波利尼西亚全基因组）、09-21（东天山古 DNA）走的是<strong>古 DNA 路线</strong>，其硬约束是「<strong>温暖湿润环境里 DNA 降解快</strong>」；而古蛋白质能在<strong>中更新世、热带外但保存条件更差</strong>的样本上工作。<strong>「换一种分子载体，就能把可研究的年代往前推一大截」<strong>是本主题值得记下的元模式：面对「数据取不到」，先问</strong>是不是把测量通道选窄了</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/paleoanthropology/index.md</code> ｜ 第41期 科学板块</p></blockquote><p>关键词：丹尼索瓦人、Denisovan、许家窑、Xujiayao、中更新世、古蛋白质组、palaeoproteomics、COL1A2-996、R&gt;K突变、哈尔滨、金牛山、大荔、华龙洞、东亚古老型人类、颅骨形态、直立人、尼安德特人、颞骨迷路、枕上凹、眶上圆枕、弱颌突、蛋白质比DNA更能穿透时间、换测量通道</p><p>关联：<code>topics/paleoanthropology/science-daily-2026-10-12.md</code>（波利尼西亚全基因组：层层奠基者效应）、<code>topics/paleoanthropology/science-daily-2026-09-21.md</code>（东天山青铜铁器古DNA）、<code>topics/paleoanthropology/index.md</code></p>',10)])])}const h=t(s,[["render",a]]);export{u as __pageData,h as default};
